FVector UCharacterMovementComponent::LimitAirControl(float DeltaTime, const FVector& FallAcceleration, const FHitResult& HitResult, bool bCheckForValidLandingSpot)
{
	FVector Result(FallAcceleration);

	if (HitResult.IsValidBlockingHit() && GetGravitySpaceZ(HitResult.Normal) > CharacterMovementConstants::VERTICAL_SLOPE_NORMAL_Z)
	{
		if (!bCheckForValidLandingSpot || !IsValidLandingSpot(HitResult.Location, HitResult))
		{
			// If acceleration is into the wall, limit contribution.
			if (FVector::DotProduct(FallAcceleration, HitResult.Normal) < 0.f)
			{
				// Allow movement parallel to the wall, but not into it because that may push us up.
				const FVector Normal2D = ProjectToGravityFloor(HitResult.Normal).GetSafeNormal();
				Result = FVector::VectorPlaneProject(FallAcceleration, Normal2D);
			}
		}
	}
	else if (HitResult.bStartPenetrating)
	{
		// Allow movement out of penetration.
		return (FVector::DotProduct(Result, HitResult.Normal) > 0.f ? Result : FVector::ZeroVector);
	}

	return Result;
}


bool UCharacterMovementComponent::CheckLedgeDirection(const FVector& OldLocation, const FVector& SideStep, const FFindFloorResult& OldFloor) const
{
	const FVector SideDest = OldLocation + SideStep;
	FCollisionQueryParams CapsuleParams(SCENE_QUERY_STAT(CheckLedgeDirection), false, CharacterOwner);

        const TCHAR* SweepKey = bRay ? TEXT("box_raycast") : bCapsule ? TEXT("capsule_sweep") : TEXT("sphere_sweep");
        if ((*Input)->HasField(SweepKey))
        {
            const TSharedPtr<FJsonObject>* Sweep = nullptr;
            TArray<double> BoxTranslationValues, BoxHalfExtentsValues, StartValues, DirectionValues;
            double Radius = 0;
            double HalfHeight = 0;
            double Length = 0;
            if (!(*Input)->TryGetObjectField(SweepKey, Sweep)
                || !ReadArray(*Sweep, TEXT("box_translation_cm"), BoxTranslationValues, 3)
                || !ReadArray(*Sweep, TEXT("box_half_extents_cm"), BoxHalfExtentsValues, 3)
                || !ReadArray(*Sweep, TEXT("start_cm"), StartValues, 3)
                || !ReadArray(*Sweep, TEXT("direction"), DirectionValues, 3)
                || (!bRay && (!(*Sweep)->TryGetNumberField(TEXT("radius_cm"), Radius) || !FMath::IsFinite(Radius) || Radius <= 0))
                || (bCapsule && (!(*Sweep)->TryGetNumberField(TEXT("half_height_cm"), HalfHeight) || !FMath::IsFinite(HalfHeight) || HalfHeight <= 0))
                || !(*Sweep)->TryGetNumberField(TEXT("length_cm"), Length) || !FMath::IsFinite(Length) || Length <= 0)
            {
                UE_LOG(LogAlsGraphSourceReader, Error, TEXT("Geometry query probe has an invalid sweep."));
                return nullptr;
            }
            const FVector BoxTranslation(BoxTranslationValues[0], BoxTranslationValues[1], BoxTranslationValues[2]);
            const FVector BoxHalfExtents(BoxHalfExtentsValues[0], BoxHalfExtentsValues[1], BoxHalfExtentsValues[2]);
            const FVector Start(StartValues[0], StartValues[1], StartValues[2]);
            const FVector Direction(DirectionValues[0], DirectionValues[1], DirectionValues[2]);
            if (BoxHalfExtents.GetMin() <= 0 || !Direction.IsNormalized()) { return nullptr; }
            FPhysicsShapeAdapter BoxAdapter(FQuat::Identity, FCollisionShape::MakeBox(BoxHalfExtents));
            Chaos::FReal Time = Length;
            Chaos::FVec3 Position = Chaos::FVec3::ZeroVector;
            Chaos::FVec3 Normal = Chaos::FVec3::ZeroVector;
            Chaos::FVec3 FaceNormal = Chaos::FVec3::ZeroVector;
            int32 FaceIndex = INDEX_NONE;
            const FTransform BoxTransform(Rotation, BoxTranslation);
            bool Hit = false;
            if (bRay)
            {
                Hit = BoxAdapter.GetGeometry().Raycast(BoxTransform.InverseTransformPositionNoScale(Start),
                    BoxTransform.InverseTransformVectorNoScale(Direction), Length, 0.0, Time, Position, Normal, FaceIndex);
                if (Hit)
                {
                    Position = BoxTransform.TransformPositionNoScale(Position);
                    Normal = BoxTransform.TransformVectorNoScale(Normal);
                }
            }
            else
            {
                FPhysicsShapeAdapter QueryAdapter(FQuat::Identity, bCapsule
                    ? FCollisionShape::MakeCapsule(Radius, HalfHeight) : FCollisionShape::MakeSphere(Radius));
                Hit = Chaos::SweepQuery(BoxAdapter.GetGeometry(), BoxTransform,
                    QueryAdapter.GetGeometry(), QueryAdapter.GetGeomPose(Start), Direction, Length, Time, Position, Normal,
                    FaceIndex, FaceNormal, 0.0, true);
            }
            TSharedRef<FJsonObject> Result = MakeShared<FJsonObject>();
            Result->SetBoolField(TEXT("hit"), Hit);
            if (Hit)
            {
                Result->SetNumberField(TEXT("distance_cm"), Time);
                Result->SetObjectField(TEXT("position_cm"), CaptureVector(FVector(Position)));
                Result->SetObjectField(TEXT("normal"), CaptureVector(FVector(Normal)));
            }
            Sample->SetObjectField(SweepKey, Result);
        }
        Samples.Add(MakeShared<FJsonValueObject>(Sample));
    }
    TSharedRef<FJsonObject> Result = MakeShared<FJsonObject>();
    Result->SetArrayField(TEXT("samples"), Samples);
    return Result;
}

pub fn movement_sweep_travel(distance: f32, hit_distance: f32) -> f32 {
    let pullback = (distance * PULLBACK_PROPORTION).clamp(PULLBACK_MIN_DISTANCE, PULLBACK_MAX_DISTANCE)
        + distance * PULLBACK_TIME_BIAS;
    (hit_distance - pullback).max(0.0)
}

pub(crate) fn falling_movement_sweep(
    spatial: &SpatialQuery, capsule: &Collider, start: Vec3, rotation: Quat,
    movement: Vec3, mut velocity: Vec3, step: f32, landing_cmc: Option<&crate::als::params::CmcAdapterParams>, entity: Entity,
    candidates: &Query<(Option<&CollisionLayers>, Has<Sensor>, Option<&ColliderOf>, Option<&AlsCollisionLayerOwnership>)>,
) -> (Vec3, Vec3, bool, Option<f32>) {
    let filter = SpatialQueryFilter::from_excluded_entities([entity]);
    let accepts = |candidate| character_blocks_collider(entity, candidate, candidates);
    let mut remaining = movement;
    let mut remaining_time = step;
    let mut previous_normal = None;
    let mut applied = Vec3::ZERO;
    let mut contact = false;
    for _ in 0..3 {
        let Ok((direction, distance)) = Dir3::new_and_length(remaining) else { break };
        let config = ShapeCastConfig { ignore_origin_penetration: true,
            ..ShapeCastConfig::from_max_distance(distance) };
        let Some(hit) = spatial.cast_shape_predicate(capsule, start + applied, rotation,
            direction, &config, &filter, &accepts) else { applied += remaining; break };
        let travel = movement_sweep_travel(distance, hit.distance);
        applied += *direction * travel;
        let Some(normal) = hit.normal1.try_normalize() else { break };
        contact |= normal.y > 0.0 && remaining.dot(normal) < 0.0;
        remaining_time *= 1.0 - travel / distance;
        if normal.y >= deg_to_rad(MAX_SLOPE_DEGREES).cos()
            && remaining.dot(normal) < 0.0
            && let Some(cmc) = landing_cmc {
            let extent = capsule.shape_scaled().compute_local_aabb().half_extents();
            let position = start + applied;
            if find_ground_floor(spatial, position, extent.y, extent.x.min(extent.z), cmc,
                LocomotionState::Air, &filter, entity, candidates)
                .is_some_and(|(center, impact, _)| (position.y - center).abs() <= MAX_FLOOR_DISTANCE
                    && impact < position.y - extent.y + extent.x.min(extent.z)) {
                return (applied, velocity, contact, Some(remaining_time));
            }
        }
        let budget = velocity * remaining_time;
        let slide = crate::extensions::motion::falling_slide(budget, normal, previous_normal);
        previous_normal = Some(normal);
        if remaining_time > f32::EPSILON { velocity = slide / remaining_time; }
        if slide.dot(budget) <= 0.0 { break; }
        remaining = slide;
    }
    (applied, velocity, contact, None)
}

pub fn falling_slide(delta: Vec3, normal: Vec3, previous_normal: Option<Vec3>) -> Vec3 {
    let slide = match previous_normal {
        Some(previous) if previous.dot(normal) <= 0.0 => {
            let crease = normal.cross(previous).normalize_or_zero();
            crease * delta.dot(crease)
        }
        _ => delta - normal * delta.dot(normal),
    };
    if slide.y <= 0.0 || slide.y - delta.y <= 1e-6 {
        return slide;
    }
    let limited = slide * (delta.y / slide.y).max(0.0);
    let remainder = Vec3::new(slide.x - limited.x, 0.0, slide.z - limited.z);
    let horizontal_normal = Vec3::new(normal.x, 0.0, normal.z).normalize_or_zero();
    limited + remainder - horizontal_normal * remainder.dot(horizontal_normal)
}

